<script>import ArcadeShell from './ArcadeShell.svelte';import {fly} from 'svelte/transition';import {onMount} from 'svelte';
export let config;export let onDone=()=>{};export let onExit=()=>{};
const reduceMotion=typeof matchMedia!=='undefined'&&matchMedia('(prefers-reduced-motion:reduce)').matches;
const W=360,H=480;let c,ctx,af,recorded=false;
let phase='briefing',levelIx=0,score=0,attempts=0,frame=0,angle=45;
let bike={x:0,y:0,vx:0,vy:0,alive:false,landed:false},particles=[],shakeTimer=0,textFade={msg:'',t:0};
let boardTop={x:0,y:0},dragging=false,dragOff={x:0,y:0};
const LEVELS=[{name:'The Angle',briefing:'Tilt the ramp. Launch the bike. Clear the gap.\n\nFeel the angle before you name it.',gaps:[{rampX:50,rampW:44,rampH:26,platX:190,platW:70,platY:390,sol:48,tol:8},{rampX:45,rampW:44,rampH:26,platX:230,platW:62,platY:370,sol:56,tol:7},{rampX:50,rampW:44,rampH:26,platX:155,platW:55,platY:410,sol:35,tol:6}],reveal:'You just used ANGLES.\n\nAn angle measures tilt from flat ground.\nSmall angle = shallow, long jump.\nLarge angle = high, short arc.'},{name:'The Fixed Board',briefing:'Only a FIXED-LENGTH board remains.\nDrag its top end — the length never changes.\nWhere must it reach?',boardLength:140,gaps:[{anchorX:80,anchorY:440,platX:210,platW:60,platY:370,solTop:{x:200,y:310},tol:18},{anchorX:70,anchorY:440,platX:240,platW:55,platY:350,solTop:{x:208,y:315},tol:16}],reveal:'That board was the HYPOTENUSE.\n\nThe longest side of a right triangle.\nIts length is fixed — its slant determines\nreach (horizontal) and height (vertical).'},{name:'The Decode',briefing:'⚠ SYSTEMS FAILING ⚠\n\nRaw data: SINE, COSINE.\nYou already know what these mean.',gaps:[{rampX:50,rampW:44,rampH:26,platX:210,platW:62,platY:380,sol:50,tol:6,glitch:true},{rampX:45,rampW:44,rampH:26,platX:175,platW:70,platY:400,sol:42,tol:5,glitch:true}],reveal:'YOU ALREADY KNEW TRIG.\n\nSINE = how much of the ramp goes UP.\nCOSINE = how much goes ACROSS.\nThe angle controls both.'}];
$:lv=LEVELS[levelIx];$:gap=lv.gaps?.[currentTarget]||null;let currentTarget=0;
function initLevel(l){levelIx=l;currentTarget=0;attempts=0;bike={x:0,y:0,vx:0,vy:0,alive:false,landed:false};particles=[];angle=45;score=0;phase='briefing';if(LEVELS[l].boardLength){const g=LEVELS[l].gaps[0];boardTop={x:g.anchorX+80,y:g.anchorY-120}}}
function launchBike(){if(phase!=='aiming')return;phase='flying';attempts++;if(lv.boardLength){const dx=gap.platX+gap.platW/2-boardTop.x,dy=gap.platY-boardTop.y,dist=Math.sqrt(dx*dx+dy*dy),spd=4.5;bike={x:boardTop.x,y:boardTop.y,vx:(dx/dist)*spd,vy:(dy/dist)*spd-1,alive:true,landed:false}}else{const rad=angle*Math.PI/180,spd=5;bike={x:gap.rampX+gap.rampW-8,y:gap.platY-gap.rampH,vx:Math.cos(rad)*spd,vy:-Math.sin(rad)*spd,alive:true,landed:false}}}
function updatePhysics(){if(!bike.alive||bike.landed)return;bike.vy+=0.25;bike.x+=bike.vx;bike.y+=bike.vy;if(frame%3===0)particles.push({x:bike.x,y:bike.y+4,vx:(Math.random()-.5)*1.2,vy:(Math.random()-.5)*1.2,life:18,color:'var(--qx-accent)'});if(bike.y>=gap.platY-8&&bike.y<=gap.platY+10&&bike.x>=gap.platX&&bike.x<=gap.platX+gap.platW){bike.landed=true;bike.x=Math.max(gap.platX,Math.min(gap.platX+gap.platW,bike.x));bike.y=gap.platY;onLand()}if(bike.y>H+40||bike.x<-40||bike.x>W+40){bike.alive=false;bike.landed=false;textFade={msg:'MISSED — retry',t:0};shakeTimer=8;setTimeout(()=>{bike={x:0,y:0,vx:0,vy:0,alive:false,landed:false};particles=[];phase='aiming'},1000)}}
function onLand(){score++;for(let i=0;i<16;i++)particles.push({x:bike.x,y:bike.y,vx:(Math.random()-.5)*5,vy:(Math.random()-.5)*5-2,life:26,color:'var(--qx-yellow)'});textFade={msg:'LANDED!',t:0};phase='landed';if(currentTarget<lv.gaps.length-1){setTimeout(()=>{currentTarget++;bike={x:0,y:0,vx:0,vy:0,alive:false,landed:false};particles=[];phase='aiming';if(LEVELS[levelIx].boardLength){const g=LEVELS[levelIx].gaps[currentTarget];boardTop={x:g.anchorX+80,y:g.anchorY-120}}},1000)}else{setTimeout(()=>{phase='reveal'},1200)}}
function finishGame(){if(recorded)return;recorded=true;onDone({id:config.id,reward:Math.min(15,6+score*2+(attempts<=lv.gaps.length+1?2:0)),arcadeScore:score*100,levelsCleared:3,perfectLevels:score>=lv.gaps.length?3:2,patternFound:true,compared:true,transferFirstTry:attempts<=lv.gaps.length+2,usedHint:false})}
function restart(){initLevel(0);recorded=false;phase='briefing'}
function handleKey(e){if(phase!=='aiming'||lv.boardLength)return;if(e.key==='ArrowLeft'||e.key==='ArrowDown')angle=Math.max(10,angle-2);if(e.key==='ArrowRight'||e.key==='ArrowUp')angle=Math.min(80,angle+2);if(e.key===' '||e.key==='Enter'){launchBike();e.preventDefault()}}
function canvasDown(e){if(!lv.boardLength||phase!=='aiming')return;const rect=c.getBoundingClientRect(),mx=(e.clientX-rect.left)*(W/rect.width),my=(e.clientY-rect.top)*(H/rect.height),dx=mx-boardTop.x,dy=my-boardTop.y;if(Math.sqrt(dx*dx+dy*dy)<30){dragging=true;dragOff={x:dx,y:dy}}}
function canvasMove(e){if(!dragging)return;const rect=c.getBoundingClientRect(),mx=(e.clientX-rect.left)*(W/rect.width)-dragOff.x,my=(e.clientY-rect.top)*(H/rect.height)-dragOff.y,dx=mx-gap.anchorX,dy=my-gap.anchorY,dist=Math.sqrt(dx*dx+dy*dy),scale=lv.boardLength/Math.max(dist,1);boardTop={x:gap.anchorX+dx*scale,y:gap.anchorY+dy*scale}}
function canvasUp(){dragging=false}
function draw(){if(!ctx)return;const d=document.documentElement.getAttribute('data-qx-theme')==='dark';ctx.fillStyle=d?'#141310':'#F2EFE8';ctx.fillRect(0,0,W,H);ctx.strokeStyle='var(--qx-border)';ctx.lineWidth=0.5;ctx.globalAlpha=0.3;for(let x=0;x<W;x+=28){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=28){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.globalAlpha=1;if(!gap)return;if(lv.boardLength){ctx.setLineDash([4,8]);ctx.strokeStyle='color-mix(in srgb, var(--qx-accent) 20%, transparent)';ctx.lineWidth=1;ctx.beginPath();ctx.arc(gap.anchorX,gap.anchorY,lv.boardLength,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='var(--qx-green)';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(gap.anchorX,gap.anchorY);ctx.lineTo(boardTop.x,boardTop.y);ctx.stroke();ctx.fillStyle='var(--qx-green)';ctx.beginPath();ctx.arc(gap.anchorX,gap.anchorY,5,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(boardTop.x,boardTop.y,7,0,Math.PI*2);ctx.fill()}else{ctx.save();ctx.translate(gap.rampX+gap.rampW,gap.platY);ctx.rotate(-angle*Math.PI/180);ctx.fillStyle='var(--qx-accent-soft)';ctx.fillRect(-gap.rampW,-gap.rampH,gap.rampW,gap.rampH);ctx.strokeStyle='var(--qx-accent)';ctx.lineWidth=2.5;ctx.strokeRect(-gap.rampW,-gap.rampH,gap.rampW,gap.rampH);ctx.beginPath();ctx.arc(0,0,22,-angle*Math.PI/180,0);ctx.strokeStyle='var(--qx-yellow)';ctx.lineWidth=2;ctx.stroke();ctx.restore()}ctx.fillStyle='var(--qx-green-soft)';ctx.fillRect(gap.platX,gap.platY,gap.platW,8);ctx.strokeStyle='var(--qx-green)';ctx.lineWidth=2;ctx.strokeRect(gap.platX,gap.platY,gap.platW,8);ctx.fillStyle='var(--qx-yellow)';ctx.fillRect(gap.platX+gap.platW/2-1,gap.platY-14,2,14);ctx.beginPath();ctx.moveTo(gap.platX+gap.platW/2,gap.platY-14);ctx.lineTo(gap.platX+gap.platW/2+10,gap.platY-9);ctx.lineTo(gap.platX+gap.platW/2,gap.platY-4);ctx.fill();if(bike.alive){ctx.save();ctx.translate(bike.x,bike.y);const tilt=bike.alive&&!bike.landed?Math.atan2(bike.vy,bike.vx)*0.25:0;ctx.rotate(tilt);ctx.fillStyle='var(--qx-accent)';ctx.fillRect(-12,-5,24,8);ctx.fillStyle='var(--qx-green)';ctx.beginPath();ctx.arc(-7,6,4.5,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(7,6,4.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='var(--qx-yellow)';ctx.fillRect(-3,-13,6,10);ctx.fillRect(-1,-15,2,4);ctx.restore()}if(!bike.alive&&phase==='aiming'&&!lv.boardLength){const rx=gap.rampX+gap.rampW-8,ry=gap.platY-gap.rampH;ctx.fillStyle='var(--qx-accent)';ctx.fillRect(rx-12,ry-7,24,8);ctx.fillStyle='var(--qx-green)';ctx.beginPath();ctx.arc(rx-7,ry+4,4.5,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(rx+7,ry+4,4.5,0,Math.PI*2);ctx.fill()}particles=particles.filter(p=>{p.life--;return p.life>0});for(const p of particles){const a=p.life/30;ctx.globalAlpha=a;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x+p.vx*0.2,p.y+p.vy*0.2,1.2,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;if(phase==='aiming'&&!lv.boardLength){ctx.fillStyle='var(--qx-accent)';ctx.font='bold 26px var(--qx-font)';ctx.textAlign='center';ctx.fillText(Math.round(angle)+'°',W/2,75);ctx.textAlign='start';ctx.font='10px var(--qx-font)';ctx.fillStyle='var(--qx-text-faint)';ctx.textAlign='center';ctx.fillText('← →  tilt ramp    SPACE  launch',W/2,100);ctx.textAlign='start'}if(phase==='aiming'&&lv.boardLength){ctx.fillStyle='var(--qx-green)';ctx.font='bold 12px var(--qx-font)';ctx.textAlign='center';ctx.fillText('DRAG the board top    SPACE to launch',W/2,65);ctx.textAlign='start'}if(textFade.t<1){textFade.t+=0.015;ctx.globalAlpha=Math.max(0,1-textFade.t);ctx.fillStyle=textFade.msg.includes('MISSED')?'var(--qx-danger)':'var(--qx-green)';ctx.font='bold 20px var(--qx-font)';ctx.textAlign='center';ctx.fillText(textFade.msg,W/2,H/2-30);ctx.textAlign='start';ctx.globalAlpha=1}if(gap.glitch&&frame%35<5){ctx.fillStyle='color-mix(in srgb, var(--qx-accent) 6%, transparent)';ctx.fillRect(Math.random()*W,Math.random()*H,Math.random()*50,Math.random()*4)}}
function loop(){frame++;if(phase==='flying')updatePhysics();if(shakeTimer>0){shakeTimer*=.82;if(shakeTimer<0.3)shakeTimer=0}if(phase!=='briefing'&&phase!=='reveal'&&c)draw();af=requestAnimationFrame(loop)}
onMount(()=>{ctx=c.getContext('2d');initLevel(0);af=requestAnimationFrame(loop);window.addEventListener('keydown',handleKey);return()=>{cancelAnimationFrame(af);window.removeEventListener('keydown',handleKey)}});
</script>
<svelte:window on:keydown={handleKey}/>
<ArcadeShell eyebrow={config.eyebrow} title={config.title} level={score} totalLevels={lv.gaps?.length||3} score={score*100} streak={score>1?score:0} onExit={onExit}>
  <canvas bind:this={c} class="pf" class:hidden={phase==='briefing'||phase==='reveal'} width={W} height={H} on:pointerdown={canvasDown} on:pointermove={canvasMove} on:pointerup={canvasUp} aria-label="Ramp Rider"></canvas>
  {#if phase==='briefing'}<div class="b" in:fly={{x:reduceMotion?0:16,duration:reduceMotion?0:200}}><h2>{lv.name}</h2><p style="white-space:pre-line">{lv.briefing}</p><button class="p" on:click={()=>phase='aiming'}>Launch</button></div>
  {:else if phase==='reveal'}<div class="r" in:fly={{x:reduceMotion?0:16,duration:reduceMotion?0:200}}><div class="k">Decoded</div><h2>{lv.name}</h2><p style="white-space:pre-line;color:var(--qx-green-text)">{lv.reveal}</p><div class="rp"><div><span>Discovery</span><strong>{config.rewardLabel}</strong></div></div>{#if levelIx<2}<button class="p" on:click={()=>initLevel(levelIx+1)}>Next mission</button>{:else}<div class="ra"><button class="p" on:click={onExit}>Return to workshops</button><button class="s" on:click={restart}>Play again</button></div>{/if}</div>{/if}
</ArcadeShell>
<style>.b,.r{display:flex;flex-direction:column;gap:10px;padding:0 4px;align-items:center;text-align:center}.k{color:var(--qx-accent-text);font-size:10px;font-weight:900;letter-spacing:.1em;text-transform:uppercase}h2{font-size:20px;line-height:1.15;margin:4px 0 6px;font-weight:950}p{color:var(--qx-text-dim);font-size:13px;line-height:1.5;margin:0}.pf{width:100%;border:1px solid var(--qx-border);border-radius:14px;background:var(--qx-bg);touch-action:none}.pf.hidden{display:none}.p,.s{min-height:46px;width:100%;border-radius:999px;font-family:var(--qx-font);font-size:14px;font-weight:900;cursor:pointer}.p{border:none;background:var(--qx-accent);color:var(--qx-bg)}.s{border:1.5px solid var(--qx-border-2);background:var(--qx-surface);color:var(--qx-text-dim);margin-top:6px}.ra{width:100%;display:grid;gap:7px}.rp{width:100%;border:1.5px solid var(--qx-green);border-radius:14px;background:var(--qx-green-soft);padding:12px;text-align:left}.rp span{font-size:9px;color:var(--qx-green-text);font-weight:900;text-transform:uppercase}.rp strong{font-size:15px}</style>
